#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    long long h;
    cin >> n >> h >> m;

    vector<long long> t(n + 1, h);

    for (int i = 0; i < m; ++i) {
        int a, b;
        long long c;
        cin >> a >> b >> c;
        for (int j = a; j <= b; ++j) {
            t[j] = min(t[j], c);
        }
    }

    long long result = 0;
    for (int i = 1; i <= n; ++i) {
        result += t[i] * t[i];
    }

    cout << result << '\n';
    return 0;
}

